def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Always defect on the final round
    if n == 99:
        return 'D'

    # Count total defections
    opp_defects = 0
    my_defects = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1

    last_m, last_o = history[-1]

    # Detect retaliation: we defected while opponent cooperated, and opponent defected next round
    retaliation = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i+1][1] == 'D':
            retaliation = True
            break

    # Exploit mode: no retaliation seen, opponent cooperated last round, and we can defect safely
    if not retaliation and n >= 10 and last_o == 'C':
        if n < 30:
            threshold = max(1, n // 10)
        else:
            threshold = int(n * 0.15)
        if my_defects + 1 <= threshold:
            return 'D'

    # Fallback: forgiving tit-for-tat with thresholds (based on the best-performing parent logic)
    if n < 10:
        if last_o == 'D':
            return 'D'
        return 'C'

    if n > 90:
        if opp_defects <= 2:
            return 'C'

    if last_o == 'C':
        return 'C'

    if n < 30:
        if opp_defects <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_defects > n * 0.3:
        return 'D'

    if opp_defects > n * 0.15:
        if last_m == 'D' and last_o == 'D':
            if n >= 2 and history[-2][1] == 'D':
                return 'C'
        return 'D'

    return 'C'
